/**
 * The CAS-capable KV **interface** — `@grok/agent-sdk/kv`.
 *
 * This module is implementation-free on purpose: it is the contract a
 * bring-your-own KV implements so conditional writes can run on it.
 * {@link HostKvCasApi} is the conditional-write superset of the plain
 * {@link HostKvApi}; {@link supportsKvCas} is the runtime probe for
 * stores of unknown provenance — a `defineStorage` backend declares CAS
 * through its `cas` group instead, so it never needs probing.
 *
 * Implementations live on the storage backends: they implement the same
 * operations as the `cas` group on `defineStorage`
 * (its `StorageCasTable` member): `fileKv` (single-process) and
 * `cursorHostedStorage` (control-plane proxy). See `docs/storage.md`.
 */
import { storageKeys } from "./storage-protocol.js";
export { supportsKvCas } from "./types.js";
/** Storage key the host KV writes for one author key. */
export function authorKvKey(agent, key) {
    return storageKeys.kv(agent, key);
}
export { createMemoryKv } from "./kv/memory-kv.js";
export { fileKv, fileKvFilePath } from "./storage-backends/file-kv.js";
export { defineStorage } from "./storage.js";
